<?php $events=$service->events();?>
<section><h3>Sicherheitsprotokolle</h3>
<div class="sec-filter-row"><label>Art<select data-table-filter="type"><option value="">Alle Arten</option><option value="firewall">Firewall</option><option value="auth">Anmeldung</option><option value="file">Dateien</option><option value="addon">Erweiterungen</option></select></label><label>Priorität<select data-table-filter="severity"><option value="">Alle Prioritäten</option><option value="critical">Kritisch</option><option value="warning">Warnung</option><option value="info">Information</option></select></label><label>Suche<input type="search" data-table-search placeholder="Ereignis oder Pfad"></label><?php if($events){?><form method="post" data-confirm="Sollen alle Sicherheitsprotokolle wirklich dauerhaft gelöscht werden?"><input type="hidden" name="sc_page" value="logs"><input type="hidden" name="action" value="logs_clear"><?php echo $admin->getFTAN();?><button class="sec-danger">Protokolle löschen</button></form><?php }?></div>
<div class="sec-scroll"><table data-events><thead><tr><th>Zeit</th><th>Priorität</th><th>Ereignis</th><th>Pfad</th></tr></thead><tbody><?php foreach($events as $event){?><tr data-type="<?php echo sec_h(strtok($event['event_type'],'.'));?>" data-severity="<?php echo sec_h($event['severity']);?>"><td><?php echo sec_h(sec_time($event['created_at']));?></td><td><span class="sec-badge <?php echo sec_h($event['severity']);?>"><?php echo sec_h($event['severity']);?></span></td><td><?php echo sec_h($event['event_type']);?></td><td class="sec-path"><?php echo sec_h($event['request_path']);?></td></tr><?php }?></tbody></table></div>
</section>
